import csv

# Read the data
data = []
with open('/tmp/saving_rates.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        data.append(row)

# Calculate yearly averages for years 1950-1990
yearly_data = {}
for row in data:
    date = row['observation_date']
    year = int(date.split('-')[0])
    if 1950 <= year <= 1990:
        rate = float(row['PSAVERT'])
        if year not in yearly_data:
            yearly_data[year] = []
        yearly_data[year].append(rate)

# Calculate averages and find peak
yearly_avg = {}
for year in range(1950, 1991):
    if year in yearly_data:
        yearly_avg[year] = sum(yearly_data[year]) / len(yearly_data[year])

# Find peak year
peak_year = None
peak_rate = None
for year, rate in sorted(yearly_avg.items()):
    if peak_rate is None or rate > peak_rate:
        peak_rate = rate
        peak_year = year

print("Yearly personal saving rates (1950-1990):")
for year in sorted(yearly_avg.keys()):
    print(f"{year}: {yearly_avg[year]:.2f}%")

print(f"\nPeak year: {peak_year} with rate {peak_rate:.2f}%")
EOF
